        ["chatGptSignInCancelled"] = ["أُلغي تسجيل الدخول أو انتهت مهلته. يمكنك المحاولة مجددًا.", "Sign-in was cancelled or timed out. You can try again.", "Connexion annulée ou délai expiré. Vous pouvez réessayer.", "Se canceló el inicio de sesión o se agotó el tiempo. Puedes intentarlo de nuevo."],
        ["chatGptSignInFailed"] = ["لم يكتمل تسجيل الدخول بـChatGPT. حاول مجددًا وتحقق من الاتصال وأهلية الحساب.", "ChatGPT sign-in did not complete. Try again and check your connection and account eligibility.", "La connexion ChatGPT n’a pas abouti. Réessayez et vérifiez la connexion et l’éligibilité du compte.", "No se completó el inicio de sesión con ChatGPT. Reintenta y comprueba la conexión y si tu cuenta es apta."],
        ["chatGptStorageError"] = ["تعذّر قراءة جلسات ChatGPT المحمية أو حفظها. تحقق من صلاحيات مجلد بيانات بصيرة وحساب ويندوز.", "Could not read or save protected ChatGPT sessions. Check the Baseera data-folder permissions and Windows account.", "Impossible de lire ou d’enregistrer les sessions ChatGPT protégées. Vérifiez les droits du dossier de données et le compte Windows.", "No se pudieron leer o guardar las sesiones protegidas. Comprueba los permisos de la carpeta de datos y la cuenta de Windows."],
        ["chatGptInvalidResponse"] = ["لم تجتز استجابة تسجيل الدخول التحقق. أعد المحاولة من بصيرة.", "The sign-in response failed validation. Start again from Baseera.", "La réponse de connexion n’a pas passé la validation. Recommencez depuis Baseera.", "La respuesta de inicio de sesión no superó la validación. Empieza de nuevo desde Baseera."],
        ["chatGptIdentityMismatch"] = ["الحساب العائد لا يطابق الحساب المحدد. اختر إضافة حساب آخر للاتصال به.", "The returned account does not match the selected account. Use Add another account to connect it.", "Le compte reçu ne correspond pas au compte choisi. Utilisez Ajouter un compte.", "La cuenta recibida no coincide con la seleccionada. Usa Añadir otra cuenta."],
        ["chatGptDeclined"] = ["لم تُمنح موافقة تسجيل الدخول. يمكنك المحاولة مجددًا أو استخدام مفتاح API.", "Sign-in consent was not granted. Try again or use an API key.", "Le consentement n’a pas été accordé. Réessayez ou utilisez une clé API.", "No se concedió la autorización. Reintenta o usa una clave API."],
        ["chatGptConsentNeeded"] = ["لم يُمنح هذا الحساب إذن استخدام خطة ChatGPT. أعد تسجيل الدخول ووافق على الإذن المطلوب إذا كان حسابك مؤهلًا.", "This account has not granted ChatGPT plan usage. Sign in again and grant the requested permission if your account is eligible.", "Ce compte n’a pas autorisé l’utilisation du forfait ChatGPT. Reconnectez-vous et accordez l’autorisation si le compte est éligible.", "Esta cuenta no autorizó el uso del plan de ChatGPT. Vuelve a iniciar sesión y concede el permiso si tu cuenta es apta."],
        ["chatGptReconnect"] = ["انتهت جلسة ChatGPT أو رُفضت. سجّل الدخول مجددًا؛ لن يُستخدم مفتاح API بدلًا منها تلقائيًا.", "The ChatGPT session expired or was rejected. Sign in again; the app will not silently switch to an API key.", "La session ChatGPT a expiré ou a été refusée. Reconnectez-vous ; aucune bascule automatique vers une clé API.", "La sesión de ChatGPT caducó o fue rechazada. Vuelve a iniciar sesión; no se cambiará automáticamente a una clave API."],
        ["chatGptReturn"] = ["استلمت بصيرة استجابة تسجيل الدخول. عد إلى التطبيق لإكمال الاتصال؛ يمكنك إغلاق هذه الصفحة.", "Baseera received the sign-in response. Return to the app to finish connecting; you can close this page.", "Baseera a reçu la réponse de connexion. Revenez dans l’application ; vous pouvez fermer cette page.", "Baseera recibió la respuesta de inicio de sesión. Vuelve a la aplicación para terminar; puedes cerrar esta página."],
        ["chatGptInvalidCallback"] = ["لم تُقبل هذه الاستجابة. أكمل المحاولة التي بدأت من بصيرة.", "This response was not accepted. Complete the attempt started in Baseera.", "Cette réponse n’a pas été acceptée. Terminez la tentative commencée dans Baseera.", "No se aceptó esta respuesta. Completa el intento iniciado desde Baseera."],
        ["chatGptSignedOut"] = ["تم تسجيل الخروج وحُذفت رموز الجلسة من هذا الجهاز.", "Signed out and removed the session tokens from this device.", "Déconnexion effectuée et jetons de session supprimés de cet appareil.", "Sesión cerrada; se eliminaron los tokens de este equipo."],
        ["chatGptRevocationUnconfirmed"] = ["حُذفت الجلسة محليًا، لكن تعذّر تأكيد إلغائها لدى OpenAI. افتح إدارة الاستخدام وافصل بصيرة من إعدادات ChatGPT.", "The local session was cleared, but OpenAI revocation could not be confirmed. Open Manage usage and disconnect Baseera in ChatGPT settings.", "La session locale a été supprimée, mais la révocation OpenAI n’a pas été confirmée. Déconnectez Baseera dans les paramètres ChatGPT.", "Se borró la sesión local, pero no se confirmó su revocación en OpenAI. Desconecta Baseera en la configuración de ChatGPT."],
        ["chatGptModelsFailed"] = ["تعذّر تحميل نماذج حساب ChatGPT.", "Could not load this ChatGPT account’s models.", "Impossible de charger les modèles de ce compte ChatGPT.", "No se pudieron cargar los modelos de esta cuenta de ChatGPT."],
        ["chatGptStreamFailed"] = ["لم يكتمل رد ChatGPT. أعد المحاولة؛ لا يُعرض الرد الجزئي كنتيجة مكتملة.", "The ChatGPT response did not complete. Try again; a partial reply is not treated as a completed result.", "La réponse ChatGPT n’est pas terminée. Réessayez ; une réponse partielle n’est pas un résultat complet.", "La respuesta de ChatGPT no se completó. Reintenta; una respuesta parcial no se trata como resultado completo."],
        ["chatGptUsageLimit"] = ["وصلت إلى حد استخدام خطة ChatGPT أو أن استخدامها غير متاح لهذا التطبيق. افتح إدارة الاستخدام لمراجعة حدود الحساب والتطبيق.", "Your ChatGPT plan usage limit was reached, or plan usage is unavailable for this app. Open Manage usage to review account and app limits.", "La limite du forfait ChatGPT a été atteinte ou son utilisation est indisponible. Ouvrez la gestion de l’utilisation pour vérifier les limites.", "Se alcanzó el límite del plan de ChatGPT o su uso no está disponible. Abre la gestión de uso para revisar los límites."],
        ["chatGptUsageOpenFailed"] = ["تعذّر فتح المتصفح. افتح chatgpt.com/settings/usage لإدارة الاستخدام.", "Could not open the browser. Visit chatgpt.com/settings/usage to manage usage.", "Impossible d’ouvrir le navigateur. Ouvrez chatgpt.com/settings/usage.", "No se pudo abrir el navegador. Visita chatgpt.com/settings/usage."],
        ["chatGptWelcomeTitle"] = ["أنت تستخدم خطة ChatGPT", "You’re using your ChatGPT plan", "Vous utilisez votre forfait ChatGPT", "Estás usando tu plan de ChatGPT"],
        ["chatGptWelcomeBody"] = ["طلبات الذكاء الاصطناعي المؤهلة في بصيرة تستخدم خطة ChatGPT أو رصيدها وفق حدود حسابك. يمكنك مراجعة الاستخدام والتحكم بوصول بصيرة من إعدادات ChatGPT. لا تُمنح بصيرة صلاحية قراءة محادثاتك.", "Eligible AI requests in Baseera use your ChatGPT plan or credits under your account limits. Review usage and manage Baseera’s access in ChatGPT settings. This does not grant access to your ChatGPT conversations.", "Les requêtes éligibles de Baseera utilisent votre forfait ChatGPT ou vos crédits selon vos limites. Gérez l’utilisation et l’accès de Baseera dans les paramètres ChatGPT. Aucun accès à vos conversations n’est accordé.", "Las solicitudes aptas de Baseera usan tu plan de ChatGPT o créditos según tus límites. Gestiona el uso y el acceso de Baseera en ChatGPT. Esto no da acceso a tus conversaciones."],
