        ["selfLatest"] = ["لديك أحدث إصدار متاح.", "You have the latest available version.", "Vous disposez de la dernière version disponible.", "Tienes la última versión disponible."],
        ["selfSaveDrafts"] = ["احفظ تعديلات الإعدادات أولًا، ثم أعد البحث عن التحديث.", "Save your settings changes first, then check again.", "Enregistrez vos modifications, puis relancez la recherche.", "Guarda los cambios de configuración y vuelve a buscar."],
        ["selfCheckFailed"] = ["تعذّر البحث عن تحديث. تحقق من الاتصال وحاول مجددًا.", "Could not check for updates. Check your connection and try again.", "Recherche impossible. Vérifiez votre connexion et réessayez.", "No se pudo buscar. Revisa tu conexión y reintenta."],
        ["selfAuto"] = ["البحث تلقائيًا عن تحديثات بصيرة", "Automatically check for Baseera updates", "Rechercher automatiquement les mises à jour de Baseera", "Buscar actualizaciones de Baseera automáticamente"],
        ["selfCheck"] = ["البحث عن تحديث", "Check for updates", "Rechercher une mise à jour", "Buscar actualizaciones"],
        ["selfSettingsNote"] = ["يُفحص مستودع بصيرة الرسمي عند الفتح، ثم كل ساعتين أثناء تشغيله. لا يبدأ التنزيل والتثبيت إلا باختيارك.", "Checks Baseera’s official repository on launch and every two hours while open. Download and installation begin when you choose.", "Vérifie le dépôt officiel au lancement puis toutes les deux heures. Le téléchargement et l’installation démarrent à votre demande.", "Consulta el repositorio oficial al iniciar y cada dos horas. La descarga e instalación empiezan cuando lo eliges."],
        ["selfPackagedOnly"] = ["التحديث الذاتي متاح في نسخة Windows المستقلة. شغّل الملف التنفيذي المنشور في GitHub.", "Self-updating requires the standalone Windows release from GitHub.", "La mise à jour intégrée nécessite la version Windows autonome publiée sur GitHub.", "La actualización integrada requiere la versión independiente de Windows publicada en GitHub."],
        ["selfRestored"] = ["تعذّر تشغيل التحديث؛ استُعيد الإصدار السابق.", "The update could not start; the previous version was restored.", "La mise à jour n’a pas démarré ; la version précédente a été restaurée.", "No se inició la actualización; se restauró la versión anterior."],
        ["welcomeCaption"] = ["مرحبًا بك", "Welcome", "Bienvenue", "Bienvenida"],
        ["welcomeTitle"] = ["مرحبًا بك في بصيرة", "Welcome to Baseera", "Bienvenue dans Baseera", "Te damos la bienvenida a Baseera"],
        ["welcomeIntro"] = ["أدوات لأعمالك اليومية على ويندوز، في مكان واحد. اختر ما تحتاجه منها.", "A few useful tools for your Windows PC, in one place. Choose the ones you need.", "Des outils utiles pour Windows, réunis au même endroit. Choisissez ceux qui vous conviennent.", "Herramientas útiles para Windows en un solo lugar. Elige las que necesitas."],
        ["welcomePrivacy"] = ["الفحص والتحويل على جهازك. تُرسل لقطة النافذة إلى خدمة الذكاء الاصطناعي التي تختارها عند طلب الترجمة فقط.", "Inspection and conversion stay on your device. Window translation sends a screenshot to your chosen AI service only on request.", "L’analyse et la conversion restent sur votre appareil. La traduction envoie une capture au service IA choisi uniquement sur demande.", "El análisis y la conversión permanecen en tu dispositivo. La traducción envía una captura al servicio de IA elegido solo cuando lo solicitas."],
        ["welcomeNext"] = ["في الخطوة التالية، تختار الأدوات التي تريد تفعيلها.", "Next, choose which tools to turn on.", "Choisissez ensuite les outils à activer.", "A continuación, elige qué herramientas activar."],
